PRAGMA foreign_keys=ON;
-- New Kaiwu sixth-cases chapter: six OCR witness panels; NONE spatially certified.
CREATE TABLE IF NOT EXISTS kaiwu_recent_panels(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),first_line INTEGER NOT NULL,last_line INTEGER NOT NULL,original_text TEXT NOT NULL,sha256 TEXT NOT NULL,source_status TEXT NOT NULL CHECK(source_status='OCR_flattened_unresolved'),metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)),PRIMARY KEY(chapter_key,case_id));
CREATE TABLE IF NOT EXISTS kaiwu_recent_panel_lines(chapter_key TEXT NOT NULL,case_id TEXT NOT NULL,source_line INTEGER NOT NULL,original_text TEXT NOT NULL,sha256 TEXT NOT NULL,PRIMARY KEY(chapter_key,case_id,source_line),FOREIGN KEY(chapter_key,case_id) REFERENCES kaiwu_recent_panels(chapter_key,case_id));
CREATE TABLE IF NOT EXISTS kaiwu_recent_source_phases(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),phase_key TEXT NOT NULL,phase_kind TEXT NOT NULL,first_line INTEGER NOT NULL,last_line INTEGER NOT NULL,source_text TEXT NOT NULL,sha256 TEXT NOT NULL,metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)),PRIMARY KEY(chapter_key,case_id,phase_key));
CREATE TABLE IF NOT EXISTS kaiwu_recent_author_steps(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),step INTEGER NOT NULL,speaker TEXT NOT NULL,first_line INTEGER NOT NULL,last_line INTEGER NOT NULL,original_text TEXT NOT NULL,sha256 TEXT NOT NULL,evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),positive_training_eligible INTEGER NOT NULL DEFAULT 0 CHECK(positive_training_eligible=0),PRIMARY KEY(chapter_key,case_id,step));
CREATE TABLE IF NOT EXISTS kaiwu_recent_unprinted_anecdotes(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),anecdote_key TEXT NOT NULL,first_line INTEGER NOT NULL,last_line INTEGER NOT NULL,source_text TEXT NOT NULL,sha256 TEXT NOT NULL,has_source_nine_palace INTEGER NOT NULL DEFAULT 0 CHECK(has_source_nine_palace=0),PRIMARY KEY(chapter_key,case_id,anecdote_key));
CREATE TABLE IF NOT EXISTS kaiwu_recent_source_corrections(chapter_key TEXT NOT NULL REFERENCES chapter_knowledge(chapter_key),case_id TEXT NOT NULL REFERENCES cases(case_id),correction_kind TEXT NOT NULL,initial_line INTEGER NOT NULL,correction_line INTEGER NOT NULL,original_initial TEXT NOT NULL,original_correction TEXT NOT NULL,no_overwriting_original_chart INTEGER NOT NULL DEFAULT 1 CHECK(no_overwriting_original_chart=1),PRIMARY KEY(chapter_key,case_id,correction_kind));
CREATE VIEW IF NOT EXISTS unified_recent_fortune_cases_all_books AS SELECT c.case_id,c.event_family_id,s.book_id,s.section_key,c.domain_id,c.known_before,c.author_judgment,c.later_feedback FROM cases c JOIN sections s ON s.section_id=c.section_id WHERE c.domain_id='life_opportunity_book_study';
